#pragma once
// Internal host wiring; a front end only needs host.h.
#include <stdint.h>

// host_prefs.cpp
void hostPrefsSetDir(const char *dir);

// host_audio.cpp: the music track the game wants now (V2's, music.h; 0 with V1), for the tests
uint8_t hostMusicWanted();
void hostPrefsFlush();

// sketch_unit.cpp (generated by gen_sketch_unit.py): the game, seen from outside
void hostGameSetup();
